insert into public.obligations (obligation_key, position, role, risk_class, high_risk_route, duty, article, applies_from, applies_if, relief_note, note, law_version) values
  ('ai-literacy', 0, 'provider', 'high_risk', null, 'Take measures to support the AI literacy of staff and others who operate or use the system on your behalf.', 'art:4:1', '2025-02-02', null, null, 'The Omnibus softened this duty: the original text required ensuring "a sufficient level of AI literacy"; the amended text requires supporting measures and no specific level.', 'amended'),
  ('ai-literacy', 1, 'provider', 'limited_risk', null, 'Take measures to support the AI literacy of staff and others who operate or use the system on your behalf.', 'art:4:1', '2025-02-02', null, null, 'The Omnibus softened this duty: the original text required ensuring "a sufficient level of AI literacy"; the amended text requires supporting measures and no specific level.', 'amended'),
  ('ai-literacy', 2, 'provider', 'minimal_risk', null, 'Take measures to support the AI literacy of staff and others who operate or use the system on your behalf.', 'art:4:1', '2025-02-02', null, null, 'The Omnibus softened this duty: the original text required ensuring "a sufficient level of AI literacy"; the amended text requires supporting measures and no specific level.', 'amended'),
  ('ai-literacy', 3, 'deployer', 'high_risk', null, 'Take measures to support the AI literacy of staff and others who operate or use the system on your behalf.', 'art:4:1', '2025-02-02', null, null, 'The Omnibus softened this duty: the original text required ensuring "a sufficient level of AI literacy"; the amended text requires supporting measures and no specific level.', 'amended'),
  ('ai-literacy', 4, 'deployer', 'limited_risk', null, 'Take measures to support the AI literacy of staff and others who operate or use the system on your behalf.', 'art:4:1', '2025-02-02', null, null, 'The Omnibus softened this duty: the original text required ensuring "a sufficient level of AI literacy"; the amended text requires supporting measures and no specific level.', 'amended'),
  ('ai-literacy', 5, 'deployer', 'minimal_risk', null, 'Take measures to support the AI literacy of staff and others who operate or use the system on your behalf.', 'art:4:1', '2025-02-02', null, null, 'The Omnibus softened this duty: the original text required ensuring "a sufficient level of AI literacy"; the amended text requires supporting measures and no specific level.', 'amended'),
  ('prohibited-practice', 6, 'provider', 'prohibited', null, 'Do not place the system on the market, put it into service or use it.', 'art:5:1', '2025-02-02', 'The practice falls under Art. 5(1) points (a) to (h).', null, null, 'amended'),
  ('prohibited-practice', 7, 'deployer', 'prohibited', null, 'Do not place the system on the market, put it into service or use it.', 'art:5:1', '2025-02-02', 'The practice falls under Art. 5(1) points (a) to (h).', null, null, 'amended'),
  ('prohibited-practice', 8, 'importer', 'prohibited', null, 'Do not place the system on the market, put it into service or use it.', 'art:5:1', '2025-02-02', 'The practice falls under Art. 5(1) points (a) to (h).', null, null, 'amended'),
  ('prohibited-intimate-imagery', 9, 'provider', 'prohibited', null, 'Do not place the system on the market, put it into service or use it.', 'art:5:1:ba', '2026-12-02', 'The system generates or manipulates realistic intimate or sexually explicit images, video or audio of an identifiable person without their explicit consent (new prohibition added by the Omnibus).', null, null, 'amended'),
  ('prohibited-intimate-imagery', 10, 'deployer', 'prohibited', null, 'Do not place the system on the market, put it into service or use it.', 'art:5:1:ba', '2026-12-02', 'The system generates or manipulates realistic intimate or sexually explicit images, video or audio of an identifiable person without their explicit consent (new prohibition added by the Omnibus).', null, null, 'amended'),
  ('prohibited-intimate-imagery', 11, 'importer', 'prohibited', null, 'Do not place the system on the market, put it into service or use it.', 'art:5:1:ba', '2026-12-02', 'The system generates or manipulates realistic intimate or sexually explicit images, video or audio of an identifiable person without their explicit consent (new prohibition added by the Omnibus).', null, null, 'amended'),
  ('prohibited-csam', 12, 'provider', 'prohibited', null, 'Do not place the system on the market, put it into service or use it.', 'art:5:1:bb', '2026-12-02', 'The system generates or manipulates child sexual abuse material (new prohibition added by the Omnibus).', null, null, 'amended'),
  ('prohibited-csam', 13, 'deployer', 'prohibited', null, 'Do not place the system on the market, put it into service or use it.', 'art:5:1:bb', '2026-12-02', 'The system generates or manipulates child sexual abuse material (new prohibition added by the Omnibus).', null, null, 'amended'),
  ('prohibited-csam', 14, 'importer', 'prohibited', null, 'Do not place the system on the market, put it into service or use it.', 'art:5:1:bb', '2026-12-02', 'The system generates or manipulates child sexual abuse material (new prohibition added by the Omnibus).', null, null, 'amended'),
  ('hr-provider-requirements', 15, 'provider', 'high_risk', 'annex_i', 'Make sure the system meets the high-risk requirements: risk management, data governance, technical documentation, logging, instructions for deployers, human oversight, accuracy, robustness and cybersecurity (Art. 9 to 15).', 'art:16:a', '2028-08-02', null, null, null, 'amended'),
  ('hr-provider-requirements', 16, 'provider', 'high_risk', 'annex_iii', 'Make sure the system meets the high-risk requirements: risk management, data governance, technical documentation, logging, instructions for deployers, human oversight, accuracy, robustness and cybersecurity (Art. 9 to 15).', 'art:16:a', '2027-12-02', null, null, null, 'amended'),
  ('hr-provider-contact', 17, 'provider', 'high_risk', 'annex_i', 'Put your name, registered trade name or trade mark and contact address on the system, its packaging or its documentation.', 'art:16:b', '2028-08-02', null, null, null, 'amended'),
  ('hr-provider-contact', 18, 'provider', 'high_risk', 'annex_iii', 'Put your name, registered trade name or trade mark and contact address on the system, its packaging or its documentation.', 'art:16:b', '2027-12-02', null, null, null, 'amended'),
  ('hr-provider-qms', 19, 'provider', 'high_risk', 'annex_i', 'Have a documented quality management system (Art. 17).', 'art:16:c', '2028-08-02', null, 'The quality management system may be proportionate to the size of the organisation for SMEs, including start-ups, and SMCs (Art. 17(2)). SMEs without partner or linked enterprises may comply with certain elements in a simplified manner (Art. 63(1)).', null, 'amended'),
  ('hr-provider-qms', 20, 'provider', 'high_risk', 'annex_iii', 'Have a documented quality management system (Art. 17).', 'art:16:c', '2027-12-02', null, 'The quality management system may be proportionate to the size of the organisation for SMEs, including start-ups, and SMCs (Art. 17(2)). SMEs without partner or linked enterprises may comply with certain elements in a simplified manner (Art. 63(1)).', null, 'amended'),
  ('hr-provider-technical-documentation', 21, 'provider', 'high_risk', 'annex_i', 'Draw up the technical documentation (Annex IV) before placing the system on the market, and keep it up to date.', 'art:11:1', '2028-08-02', null, 'SMEs, including start-ups, and SMCs may provide the Annex IV elements in a simplified manner, using the Commission''s simplified form (Art. 11(1)). As of 24 September 2026 the form did not appear to be published.', null, 'amended'),
  ('hr-provider-technical-documentation', 22, 'provider', 'high_risk', 'annex_iii', 'Draw up the technical documentation (Annex IV) before placing the system on the market, and keep it up to date.', 'art:11:1', '2027-12-02', null, 'SMEs, including start-ups, and SMCs may provide the Annex IV elements in a simplified manner, using the Commission''s simplified form (Art. 11(1)). As of 24 September 2026 the form did not appear to be published.', null, 'amended'),
  ('hr-provider-keep-documentation', 23, 'provider', 'high_risk', 'annex_i', 'Keep the technical documentation, quality management documents and declaration of conformity for 10 years (Art. 18).', 'art:16:d', '2028-08-02', null, null, null, 'amended'),
  ('hr-provider-keep-documentation', 24, 'provider', 'high_risk', 'annex_iii', 'Keep the technical documentation, quality management documents and declaration of conformity for 10 years (Art. 18).', 'art:16:d', '2027-12-02', null, null, null, 'amended'),
  ('hr-provider-logs', 25, 'provider', 'high_risk', 'annex_i', 'Keep the logs the system generates automatically, where they are under your control (Art. 19).', 'art:16:e', '2028-08-02', null, null, null, 'amended'),
  ('hr-provider-logs', 26, 'provider', 'high_risk', 'annex_iii', 'Keep the logs the system generates automatically, where they are under your control (Art. 19).', 'art:16:e', '2027-12-02', null, null, null, 'amended'),
  ('hr-provider-conformity-assessment', 27, 'provider', 'high_risk', 'annex_i', 'Have the system undergo the relevant conformity assessment (Art. 43) before placing it on the market or putting it into service.', 'art:16:f', '2028-08-02', null, null, null, 'amended'),
  ('hr-provider-conformity-assessment', 28, 'provider', 'high_risk', 'annex_iii', 'Have the system undergo the relevant conformity assessment (Art. 43) before placing it on the market or putting it into service.', 'art:16:f', '2027-12-02', null, null, null, 'amended'),
  ('hr-provider-declaration', 29, 'provider', 'high_risk', 'annex_i', 'Draw up an EU declaration of conformity (Art. 47).', 'art:16:g', '2028-08-02', null, null, null, 'amended'),
  ('hr-provider-declaration', 30, 'provider', 'high_risk', 'annex_iii', 'Draw up an EU declaration of conformity (Art. 47).', 'art:16:g', '2027-12-02', null, null, null, 'amended'),
  ('hr-provider-ce-marking', 31, 'provider', 'high_risk', 'annex_i', 'Affix the CE marking to the system, its packaging or its documentation (Art. 48).', 'art:16:h', '2028-08-02', null, null, null, 'amended'),
  ('hr-provider-ce-marking', 32, 'provider', 'high_risk', 'annex_iii', 'Affix the CE marking to the system, its packaging or its documentation (Art. 48).', 'art:16:h', '2027-12-02', null, null, null, 'amended'),
  ('hr-provider-registration', 33, 'provider', 'high_risk', 'annex_iii', 'Register yourself and the system in the EU database before placing it on the market (Art. 49(1)).', 'art:16:i', '2027-12-02', null, null, 'Systems in Annex III point 2 (critical infrastructure) are registered at national level instead (Art. 49(5)).', 'amended'),
  ('hr-provider-corrective-actions', 34, 'provider', 'high_risk', 'annex_i', 'Take corrective action and inform others when the system is not in conformity (Art. 20).', 'art:16:j', '2028-08-02', null, null, null, 'amended'),
  ('hr-provider-corrective-actions', 35, 'provider', 'high_risk', 'annex_iii', 'Take corrective action and inform others when the system is not in conformity (Art. 20).', 'art:16:j', '2027-12-02', null, null, null, 'amended'),
  ('hr-provider-demonstrate-conformity', 36, 'provider', 'high_risk', 'annex_i', 'Demonstrate the system''s conformity when a national competent authority asks.', 'art:16:k', '2028-08-02', null, null, null, 'amended'),
  ('hr-provider-demonstrate-conformity', 37, 'provider', 'high_risk', 'annex_iii', 'Demonstrate the system''s conformity when a national competent authority asks.', 'art:16:k', '2027-12-02', null, null, null, 'amended'),
  ('hr-provider-accessibility', 38, 'provider', 'high_risk', 'annex_i', 'Make sure the system meets the accessibility requirements of Directives (EU) 2016/2102 and (EU) 2019/882.', 'art:16:l', '2028-08-02', null, null, null, 'amended'),
  ('hr-provider-accessibility', 39, 'provider', 'high_risk', 'annex_iii', 'Make sure the system meets the accessibility requirements of Directives (EU) 2016/2102 and (EU) 2019/882.', 'art:16:l', '2027-12-02', null, null, null, 'amended'),
  ('hr-provider-authorised-representative', 40, 'provider', 'high_risk', 'annex_i', 'Appoint an authorised representative established in the Union, by written mandate, before making the system available.', 'art:22:1', '2028-08-02', 'The provider is established outside the Union.', null, null, 'amended'),
  ('hr-provider-authorised-representative', 41, 'provider', 'high_risk', 'annex_iii', 'Appoint an authorised representative established in the Union, by written mandate, before making the system available.', 'art:22:1', '2027-12-02', 'The provider is established outside the Union.', null, null, 'amended'),
  ('hr-provider-post-market-monitoring', 42, 'provider', 'high_risk', 'annex_i', 'Set up and document a post-market monitoring system based on a monitoring plan.', 'art:72:1', '2028-08-02', null, null, 'Art. 72 is in Chapter IX, which applies from 2 August 2026, but it only bites on systems that are subject to the high-risk rules, so the high-risk date is used here.', 'amended'),
  ('hr-provider-post-market-monitoring', 43, 'provider', 'high_risk', 'annex_iii', 'Set up and document a post-market monitoring system based on a monitoring plan.', 'art:72:1', '2027-12-02', null, null, 'Art. 72 is in Chapter IX, which applies from 2 August 2026, but it only bites on systems that are subject to the high-risk rules, so the high-risk date is used here.', 'amended'),
  ('hr-provider-serious-incidents', 44, 'provider', 'high_risk', 'annex_i', 'Report serious incidents to the market surveillance authority: at the latest 15 days after becoming aware, 10 days in case of death, 2 days for a widespread infringement.', 'art:73:1', '2028-08-02', null, null, 'Art. 73 is in Chapter IX, which applies from 2 August 2026, but it only bites on systems that are subject to the high-risk rules, so the high-risk date is used here.', 'amended'),
  ('hr-provider-serious-incidents', 45, 'provider', 'high_risk', 'annex_iii', 'Report serious incidents to the market surveillance authority: at the latest 15 days after becoming aware, 10 days in case of death, 2 days for a widespread infringement.', 'art:73:1', '2027-12-02', null, null, 'Art. 73 is in Chapter IX, which applies from 2 August 2026, but it only bites on systems that are subject to the high-risk rules, so the high-risk date is used here.', 'amended'),
  ('hr-deployer-instructions', 46, 'deployer', 'high_risk', 'annex_i', 'Use the system according to the provider''s instructions for use, with appropriate technical and organisational measures.', 'art:26:1', '2028-08-02', null, null, null, 'amended'),
  ('hr-deployer-instructions', 47, 'deployer', 'high_risk', 'annex_iii', 'Use the system according to the provider''s instructions for use, with appropriate technical and organisational measures.', 'art:26:1', '2027-12-02', null, null, null, 'amended'),
  ('hr-deployer-human-oversight', 48, 'deployer', 'high_risk', 'annex_i', 'Assign human oversight to people with the necessary competence, training, authority and support.', 'art:26:2', '2028-08-02', null, null, null, 'amended'),
  ('hr-deployer-human-oversight', 49, 'deployer', 'high_risk', 'annex_iii', 'Assign human oversight to people with the necessary competence, training, authority and support.', 'art:26:2', '2027-12-02', null, null, null, 'amended'),
  ('hr-deployer-input-data', 50, 'deployer', 'high_risk', 'annex_i', 'Make sure the input data is relevant and sufficiently representative for the intended purpose.', 'art:26:4', '2028-08-02', 'You control the input data.', null, null, 'amended'),
  ('hr-deployer-input-data', 51, 'deployer', 'high_risk', 'annex_iii', 'Make sure the input data is relevant and sufficiently representative for the intended purpose.', 'art:26:4', '2027-12-02', 'You control the input data.', null, null, 'amended'),
  ('hr-deployer-monitoring', 52, 'deployer', 'high_risk', 'annex_i', 'Monitor the system''s operation; if it presents a risk, inform the provider or distributor and the market surveillance authority and suspend its use; report serious incidents to the provider first.', 'art:26:5', '2028-08-02', null, null, null, 'amended'),
  ('hr-deployer-monitoring', 53, 'deployer', 'high_risk', 'annex_iii', 'Monitor the system''s operation; if it presents a risk, inform the provider or distributor and the market surveillance authority and suspend its use; report serious incidents to the provider first.', 'art:26:5', '2027-12-02', null, null, null, 'amended'),
  ('hr-deployer-logs', 54, 'deployer', 'high_risk', 'annex_i', 'Keep the logs the system generates, where they are under your control, for at least six months.', 'art:26:6', '2028-08-02', null, null, null, 'amended'),
  ('hr-deployer-logs', 55, 'deployer', 'high_risk', 'annex_iii', 'Keep the logs the system generates, where they are under your control, for at least six months.', 'art:26:6', '2027-12-02', null, null, null, 'amended'),
  ('hr-deployer-inform-workers', 56, 'deployer', 'high_risk', 'annex_i', 'Inform workers'' representatives and the affected workers before using the system at the workplace.', 'art:26:7', '2028-08-02', 'You are an employer and use the system at the workplace.', null, null, 'amended'),
  ('hr-deployer-inform-workers', 57, 'deployer', 'high_risk', 'annex_iii', 'Inform workers'' representatives and the affected workers before using the system at the workplace.', 'art:26:7', '2027-12-02', 'You are an employer and use the system at the workplace.', null, null, 'amended'),
  ('hr-deployer-registration', 58, 'deployer', 'high_risk', 'annex_iii', 'Register the use of the system in the EU database (Art. 49(3)); do not use a system that is not registered.', 'art:26:8', '2027-12-02', 'You are a public authority or a Union institution, body, office or agency.', null, null, 'amended'),
  ('hr-deployer-dpia', 59, 'deployer', 'high_risk', 'annex_i', 'Use the provider''s information (Art. 13) for your data protection impact assessment.', 'art:26:9', '2028-08-02', 'A data protection impact assessment is required under Art. 35 GDPR or Art. 27 of Directive (EU) 2016/680.', null, null, 'amended'),
  ('hr-deployer-dpia', 60, 'deployer', 'high_risk', 'annex_iii', 'Use the provider''s information (Art. 13) for your data protection impact assessment.', 'art:26:9', '2027-12-02', 'A data protection impact assessment is required under Art. 35 GDPR or Art. 27 of Directive (EU) 2016/680.', null, null, 'amended'),
  ('hr-deployer-inform-persons', 61, 'deployer', 'high_risk', 'annex_iii', 'Inform the people concerned that they are subject to the use of the high-risk system.', 'art:26:11', '2027-12-02', 'The system makes, or helps make, decisions about natural persons.', null, null, 'amended'),
  ('hr-deployer-cooperate', 62, 'deployer', 'high_risk', 'annex_i', 'Cooperate with the competent authorities in any action they take about the system.', 'art:26:12', '2028-08-02', null, null, null, 'amended'),
  ('hr-deployer-cooperate', 63, 'deployer', 'high_risk', 'annex_iii', 'Cooperate with the competent authorities in any action they take about the system.', 'art:26:12', '2027-12-02', null, null, null, 'amended'),
  ('hr-deployer-fria', 64, 'deployer', 'high_risk', 'annex_iii', 'Carry out a fundamental rights impact assessment before first use, and notify the market surveillance authority of the results.', 'art:27:1', '2027-12-02', 'You are a body governed by public law or a private entity providing public services (except for Annex III point 2), or the system is used for creditworthiness or credit scoring, or for risk assessment and pricing in life and health insurance (Annex III points 5(b) and (c)).', null, 'The AI Office is to publish a questionnaire template to simplify this assessment (Art. 27(5)).', 'amended'),
  ('hr-importer-verify', 65, 'importer', 'high_risk', 'annex_i', 'Before placing the system on the market, verify that the provider carried out the conformity assessment, drew up the technical documentation, affixed the CE marking with the declaration of conformity and instructions, and appointed an authorised representative.', 'art:23:1', '2028-08-02', null, null, null, 'amended'),
  ('hr-importer-verify', 66, 'importer', 'high_risk', 'annex_iii', 'Before placing the system on the market, verify that the provider carried out the conformity assessment, drew up the technical documentation, affixed the CE marking with the declaration of conformity and instructions, and appointed an authorised representative.', 'art:23:1', '2027-12-02', null, null, null, 'amended'),
  ('hr-importer-nonconformity', 67, 'importer', 'high_risk', 'annex_i', 'Do not place a non-conforming or falsified system on the market; if it presents a risk, inform the provider, the authorised representative and the authorities.', 'art:23:2', '2028-08-02', null, null, null, 'amended'),
  ('hr-importer-nonconformity', 68, 'importer', 'high_risk', 'annex_iii', 'Do not place a non-conforming or falsified system on the market; if it presents a risk, inform the provider, the authorised representative and the authorities.', 'art:23:2', '2027-12-02', null, null, null, 'amended'),
  ('hr-importer-contact', 69, 'importer', 'high_risk', 'annex_i', 'Put your name, registered trade name or trade mark and contact address on the system and its packaging or documentation.', 'art:23:3', '2028-08-02', null, null, null, 'amended'),
  ('hr-importer-contact', 70, 'importer', 'high_risk', 'annex_iii', 'Put your name, registered trade name or trade mark and contact address on the system and its packaging or documentation.', 'art:23:3', '2027-12-02', null, null, null, 'amended'),
  ('hr-importer-storage', 71, 'importer', 'high_risk', 'annex_i', 'Make sure storage and transport do not jeopardise the system''s compliance while it is under your responsibility.', 'art:23:4', '2028-08-02', null, null, null, 'amended'),
  ('hr-importer-storage', 72, 'importer', 'high_risk', 'annex_iii', 'Make sure storage and transport do not jeopardise the system''s compliance while it is under your responsibility.', 'art:23:4', '2027-12-02', null, null, null, 'amended'),
  ('hr-importer-keep-documents', 73, 'importer', 'high_risk', 'annex_i', 'Keep the notified body''s certificate (if any), the instructions for use and the declaration of conformity for 10 years.', 'art:23:5', '2028-08-02', null, null, null, 'amended'),
  ('hr-importer-keep-documents', 74, 'importer', 'high_risk', 'annex_iii', 'Keep the notified body''s certificate (if any), the instructions for use and the declaration of conformity for 10 years.', 'art:23:5', '2027-12-02', null, null, null, 'amended'),
  ('hr-importer-provide-information', 75, 'importer', 'high_risk', 'annex_i', 'Give the competent authorities the information and documentation they ask for to demonstrate conformity.', 'art:23:6', '2028-08-02', null, null, null, 'amended'),
  ('hr-importer-provide-information', 76, 'importer', 'high_risk', 'annex_iii', 'Give the competent authorities the information and documentation they ask for to demonstrate conformity.', 'art:23:6', '2027-12-02', null, null, null, 'amended'),
  ('hr-importer-cooperate', 77, 'importer', 'high_risk', 'annex_i', 'Cooperate with the competent authorities in any action they take about the system.', 'art:23:7', '2028-08-02', null, null, null, 'amended'),
  ('hr-importer-cooperate', 78, 'importer', 'high_risk', 'annex_iii', 'Cooperate with the competent authorities in any action they take about the system.', 'art:23:7', '2027-12-02', null, null, null, 'amended'),
  ('hr-distributor-verify', 79, 'distributor', 'high_risk', 'annex_i', 'Before making the system available, verify the CE marking, the declaration of conformity and instructions for use, and that the provider and importer put their names and contact details on it.', 'art:24:1', '2028-08-02', null, null, null, 'amended'),
  ('hr-distributor-verify', 80, 'distributor', 'high_risk', 'annex_iii', 'Before making the system available, verify the CE marking, the declaration of conformity and instructions for use, and that the provider and importer put their names and contact details on it.', 'art:24:1', '2027-12-02', null, null, null, 'amended'),
  ('hr-distributor-nonconformity', 81, 'distributor', 'high_risk', 'annex_i', 'Do not make a non-conforming system available; if it presents a risk, inform the provider or importer.', 'art:24:2', '2028-08-02', null, null, null, 'amended'),
  ('hr-distributor-nonconformity', 82, 'distributor', 'high_risk', 'annex_iii', 'Do not make a non-conforming system available; if it presents a risk, inform the provider or importer.', 'art:24:2', '2027-12-02', null, null, null, 'amended'),
  ('hr-distributor-storage', 83, 'distributor', 'high_risk', 'annex_i', 'Make sure storage and transport do not jeopardise the system''s compliance while it is under your responsibility.', 'art:24:3', '2028-08-02', null, null, null, 'amended'),
  ('hr-distributor-storage', 84, 'distributor', 'high_risk', 'annex_iii', 'Make sure storage and transport do not jeopardise the system''s compliance while it is under your responsibility.', 'art:24:3', '2027-12-02', null, null, null, 'amended'),
  ('hr-distributor-corrective-actions', 85, 'distributor', 'high_risk', 'annex_i', 'For a non-conforming system you made available, take corrective action, withdraw or recall it, or make sure the provider or importer does.', 'art:24:4', '2028-08-02', null, null, null, 'amended'),
  ('hr-distributor-corrective-actions', 86, 'distributor', 'high_risk', 'annex_iii', 'For a non-conforming system you made available, take corrective action, withdraw or recall it, or make sure the provider or importer does.', 'art:24:4', '2027-12-02', null, null, null, 'amended'),
  ('hr-distributor-provide-information', 87, 'distributor', 'high_risk', 'annex_i', 'Give the competent authorities the information and documentation they ask for about your actions.', 'art:24:5', '2028-08-02', null, null, null, 'amended'),
  ('hr-distributor-provide-information', 88, 'distributor', 'high_risk', 'annex_iii', 'Give the competent authorities the information and documentation they ask for about your actions.', 'art:24:5', '2027-12-02', null, null, null, 'amended'),
  ('hr-distributor-cooperate', 89, 'distributor', 'high_risk', 'annex_i', 'Cooperate with the competent authorities in any action they take about the system.', 'art:24:6', '2028-08-02', null, null, null, 'amended'),
  ('hr-distributor-cooperate', 90, 'distributor', 'high_risk', 'annex_iii', 'Cooperate with the competent authorities in any action they take about the system.', 'art:24:6', '2027-12-02', null, null, null, 'amended'),
  ('transparency-interaction', 91, 'provider', 'limited_risk', null, 'Design the system so that people are informed they are interacting with an AI system, unless that is obvious.', 'art:50:1', '2026-08-02', 'The system is intended to interact directly with natural persons.', null, null, 'amended'),
  ('transparency-interaction', 92, 'provider', 'high_risk', null, 'Design the system so that people are informed they are interacting with an AI system, unless that is obvious.', 'art:50:1', '2026-08-02', 'The system is intended to interact directly with natural persons.', null, null, 'amended'),
  ('transparency-marking', 93, 'provider', 'limited_risk', null, 'Mark the system''s outputs in a machine-readable format so they are detectable as artificially generated or manipulated.', 'art:50:2', '2026-08-02', 'The system generates synthetic audio, image, video or text content.', null, 'Systems placed on the market before 2 August 2026 have until 2 December 2026 to comply (Art. 111(4), added by the Omnibus).', 'amended'),
  ('transparency-marking', 94, 'provider', 'high_risk', null, 'Mark the system''s outputs in a machine-readable format so they are detectable as artificially generated or manipulated.', 'art:50:2', '2026-08-02', 'The system generates synthetic audio, image, video or text content.', null, 'Systems placed on the market before 2 August 2026 have until 2 December 2026 to comply (Art. 111(4), added by the Omnibus).', 'amended'),
  ('transparency-emotion-biometric', 95, 'deployer', 'limited_risk', null, 'Inform the people exposed to the system that it is operating, and process their personal data under the GDPR.', 'art:50:3', '2026-08-02', 'The system is an emotion recognition or biometric categorisation system.', null, null, 'amended'),
  ('transparency-emotion-biometric', 96, 'deployer', 'high_risk', null, 'Inform the people exposed to the system that it is operating, and process their personal data under the GDPR.', 'art:50:3', '2026-08-02', 'The system is an emotion recognition or biometric categorisation system.', null, null, 'amended'),
  ('transparency-deep-fake', 97, 'deployer', 'limited_risk', null, 'Disclose that deep-fake image, audio or video content, or text published to inform the public on matters of public interest, has been artificially generated or manipulated.', 'art:50:4', '2026-08-02', 'The system generates or manipulates deep fakes, or text published to inform the public on matters of public interest (not needed for text under human editorial control).', null, null, 'amended'),
  ('transparency-deep-fake', 98, 'deployer', 'high_risk', null, 'Disclose that deep-fake image, audio or video content, or text published to inform the public on matters of public interest, has been artificially generated or manipulated.', 'art:50:4', '2026-08-02', 'The system generates or manipulates deep fakes, or text published to inform the public on matters of public interest (not needed for text under human editorial control).', null, null, 'amended'),
  ('annex-iii-exemption', 99, 'provider', 'limited_risk', null, 'Document the assessment before placing the system on the market, register it in the EU database (Art. 49(2)), and hand the assessment to national authorities on request.', 'art:6:4', '2027-12-02', 'The system is listed in Annex III, but you concluded under Art. 6(3) that it is not high-risk.', null, 'The Omnibus kept this registration but simplified its content (Omnibus recital 22). The date follows Art. 113(c)(i), which applies Chapter III Sections 1 to 3 to Annex III systems from 2 December 2027.', 'amended'),
  ('annex-iii-exemption', 100, 'provider', 'minimal_risk', null, 'Document the assessment before placing the system on the market, register it in the EU database (Art. 49(2)), and hand the assessment to national authorities on request.', 'art:6:4', '2027-12-02', 'The system is listed in Annex III, but you concluded under Art. 6(3) that it is not high-risk.', null, 'The Omnibus kept this registration but simplified its content (Omnibus recital 22). The date follows Art. 113(c)(i), which applies Chapter III Sections 1 to 3 to Annex III systems from 2 December 2027.', 'amended');
